  "v.orig": "ଯେଉଁ ଇନଭଏସ ପାଇଁ ଏହି ନୋଟ, ତାର ନମ୍ବର ଓ ତାରିଖ ଲେଖନ୍ତୁ। GST ନିୟମରେ ନୋଟରେ ଏସବୁ ଦରକାର।",
  "v.naddr": "GSTIN ନଥିବା ବାୟରଙ୍କ ଠିକଣା ଓ ରାଜ୍ୟ ଲେଖନ୍ତୁ।",
  "c.cn30": "ଏହି କ୍ରେଡିଟ୍ ନୋଟର ତାରିଖ ସେହି ଇନଭଏସର ଫାଇନାନ୍ସିଆଲ ଇୟର ଶେଷ ହେବା ପରର 30 ନଭେମ୍ବର ପରେ (ବା ସେହି ବର୍ଷର ବାର୍ଷିକ ରିଟର୍ନ ତା ଆଗରୁ ଫାଇଲ କରିଥିଲେ, ତା ପରେ)। ସେହି ତାରିଖ ପରେ ଏଥିରେ GST ଆଉ କମାଯାଇପାରିବ ନାହିଁ (ବିଜନେସ କାଗଜ ଭାବେ ନୋଟ ତଥାପି ଚାଲିବ)। ତଥାପି ସେଭ କରିବେ?",
  "s.tds": "ଟଙ୍କା ଦେଉଥିବା ବ୍ୟକ୍ତି କାଟିଥିବା TDS (₹)",
  "s.h.tds": "କେବଳ ଯଦି ଟଙ୍କା ଦେଉଥିବା ବ୍ୟକ୍ତି TDS କାଟିଛନ୍ତି। ରସିଦରେ TDS ଓ ସେଟଲ ହୋଇଥିବା ପୂରା ବିଲ ରାଶି ଦେଖାଯିବ।",
  "c.cash10k": "ଇନକମ ଟ୍ୟାକ୍ସ ଆଇନରେ ଜଣକୁ ଦିନକରେ ₹10,000ରୁ ଅଧିକ ନଗଦ ପେମେଣ୍ଟ ବିଜନେସ ଖର୍ଚ୍ଚ ଭାବେ ଧରାଯାଏ ନାହିଁ (ଟ୍ରାନ୍ସପୋର୍ଟରଙ୍କ ପାଇଁ ₹35,000)। ତଥାପି ସେଭ କରିବେ?",
