  "s.v.rv": "ଏହି ରିଫଣ୍ଡ ଯେଉଁ ରିସିପ୍ଟ ଭାଉଚର୍ ପାଇଁ, ତାର ନମ୍ବର ଲେଖନ୍ତୁ।",
  "s.lg.tdsrcm": "TDS ଓ ରିଭର୍ସ ଚାର୍ଜ",
  "s.tdssec": "TDS ସେକ୍ସନ",
  "s.h.tdssec": "ସେକ୍ସନ ବାଛନ୍ତୁ ବା ଲେଖନ୍ତୁ, ଯେପରି 393 (ପୁରୁଣା 194C)। ନିଶ୍ଚିତ ନଥିଲେ ଆପଣଙ୍କ ଆକାଉଣ୍ଟାଣ୍ଟଙ୍କୁ ପଚାରନ୍ତୁ।",
