  "s.pt.manual": "ଏହି ରାଜ୍ୟର ପ୍ରଫେସନାଲ ଟ୍ୟାକ୍ସ ଏଯାଏଁ ଆମ ଟେବୁଲରେ ନାହିଁ। ପ୍ରଫେସନାଲ ଟ୍ୟାକ୍ସ ଲାଇନରେ ନିଜେ ଲେଖନ୍ତୁ।",
  "s.pfbtn2": "PF, ESI, ପ୍ରଫେସନାଲ ଟ୍ୟାକ୍ସ ଓ TDS ହିସାବ କରନ୍ତୁ",
  "s.h.pf2": "PF: ବେସିକ୍‌ର 12% (₹25,000 ପର୍ଯ୍ୟନ୍ତ ବେସିକ୍‌ରେ); ESI: ଗ୍ରସ୍ ₹21,000 କିମ୍ବା କମ୍ ହେଲେ 0.75%; ପ୍ରଫେସନାଲ ଟ୍ୟାକ୍ସ ଉପରେ ବାଛିଥିବା ରାଜ୍ୟ ଅନୁସାରେ; TDS: ଏହି ମାସର ଗ୍ରସ୍ × 12, FY 2026-27ର ସ୍ଲାବ୍ ଓ ଷ୍ଟାଣ୍ଡାର୍ଡ ଡିଡକ୍ସନ ଧରି। ନିଜ ନିୟମ ସହ ମିଳାଇ ଦେଖନ୍ତୁ।",
  "s.w.wages": "ବେସିକ୍ ପେ ଗ୍ରସ୍‌ର ଅଧାରୁ କମ୍। ଲେବର କୋଡ୍ ଅନୁସାରେ ଅତିରିକ୍ତ ଆଲାଉନ୍ସ PF ଓ ଗ୍ରାଚୁଇଟି ପାଇଁ ୱେଜ୍ ଭାବେ ଗଣାଯାଏ।",
