  "app.local": "ଡାଟା ହୋମ ଖୋଲିଲା ନାହିଁ, ତେଣୁ କେବଳ ଏହି ସାଇଟରେ ଏହି ବ୍ରାଉଜରରେ ସେଭ ଅଛି। ପରଥର ଏହା ଡାଟା ହୋମକୁ ଚାଲିଯିବ।",
  "app.vault": "ଏହି ବ୍ରାଉଜରର ଡାଟା ହୋମରେ ସେଭ ଅଛି, ଯାହା Nivesh Sahayak ର ସବୁ ଟୁଲରେ ଶେୟାର। ଆମକୁ କିଛି ପଠାଯାଏ ନାହିଁ।",
