  "bk.zero": "ଡକ୍ୟୁମେଣ୍ଟ ଟାଇପ୍ {v} ହେଲେ ପୋର୍ଟାଲରେ ପ୍ରତ୍ୟେକ ଆଇଟମ୍‌ରେ GST 0% ଲାଗେ।",
