  'nav.gstr3b': 'GSTR-3B ହିସାବ', 'f.gstr3b': 'GSTR-3B ୱାର୍କିଂ ସିଟ୍',
  'g3.nobiz': 'ଏପର୍ଯ୍ୟନ୍ତ କୌଣସି ବିଜନେସ୍ ସେଭ୍ ହୋଇନାହିଁ', 'g3.refill': 'ସେଭ୍ ହୋଇଥିବା ବିଲ୍‌ରୁ ପୁଣି ଭରନ୍ତୁ', 'g3.save': 'ଏହି ହିସାବ ସେଭ୍ କରନ୍ତୁ', 'g3.saved': 'ହିସାବ ଆପଣଙ୍କ ଡାଟା ହୋମ୍‌ରେ ସେଭ୍ ହେଲା।', 'g3.refilled': 'ଆପଣଙ୍କ ସେଭ୍ ହୋଇଥିବା ବିଲ୍‌ରୁ ଅଙ୍କ ପୁଣି ଭରାଗଲା।',
  'g3.loaded': '{d} ରେ ସେଭ୍ ହୋଇଥିବା ଆପଣଙ୍କ ହିସାବ ଦେଖାଯାଉଛି। ନୂଆକରି ଆରମ୍ଭ କରିବାକୁ “ସେଭ୍ ହୋଇଥିବା ବିଲ୍‌ରୁ ପୁଣି ଭରନ୍ତୁ” ଦବାନ୍ତୁ।',
  'g3.formh': 'ଆପଣଙ୍କ ସେଭ୍ ହୋଇଥିବା ବିଲ୍‌ର ଅଙ୍କ ଭରାଯାଇଛି। ଯେକୌଣସି ବକ୍ସରେ ନିଜେ ଟାଇପ୍ କରିପାରିବେ, ଯେପରି ଆପଣଙ୍କ GSTR-2B ରେ ଦେଖାଯାଉଥିବା ITC। ଆପଣ ବଦଳାଇଥିବା ବକ୍ସ ଚିହ୍ନିତ ହେବ।',
  'g3.h.out': '3.1 ଆଉଟୱାର୍ଡ ସପ୍ଲାଇ ଓ ରିଭର୍ସ ଚାର୍ଜ ସପ୍ଲାଇ ଉପରେ ଟ୍ୟାକ୍ସ', 'g3.h.itc': '4(A) ମିଳିଥିବା ଇନପୁଟ୍ ଟ୍ୟାକ୍ସ କ୍ରେଡିଟ୍', 'g3.h.rev': '4(B) ଫେରାଇ ଦିଆଯାଇଥିବା ଇନପୁଟ୍ ଟ୍ୟାକ୍ସ କ୍ରେଡିଟ୍', 'g3.h.exin': '5 ଛାଡ଼, ନିଲ୍ ଓ ନନ୍-GST ଇନୱାର୍ଡ ସପ୍ଲାଇ', 'g3.h.more': 'ଆଗରୁ ଆସିଥିବା କ୍ରେଡିଟ୍, ସୁଧ ଓ ଲେଟ୍ ଫି',
  'g3.b.a': '(a) ଟ୍ୟାକ୍ସ ଲାଗୁଥିବା ଆଉଟୱାର୍ଡ ସପ୍ଲାଇ', 'g3.b.b': '(b) ଜିରୋ ରେଟେଡ୍ (ଏକ୍ସପୋର୍ଟ, SEZ)', 'g3.b.c': '(c) ନିଲ୍ ରେଟେଡ୍ ଓ ଛାଡ଼ ପାଇଥିବା', 'g3.b.d': '(d) ରିଭର୍ସ ଚାର୍ଜରେ ଇନୱାର୍ଡ ସପ୍ଲାଇ', 'g3.b.e': '(e) ନନ୍-GST ଆଉଟୱାର୍ଡ ସପ୍ଲାଇ',
  'g3.b.i1': '(1) ଗୁଡ୍ସ ଇମ୍ପୋର୍ଟ', 'g3.b.i2': '(2) ସର୍ଭିସ୍ ଇମ୍ପୋର୍ଟ', 'g3.b.i3': '(3) ରିଭର୍ସ ଚାର୍ଜରେ ଇନୱାର୍ଡ ସପ୍ଲାଇ', 'g3.b.i4': '(4) ISD ଠାରୁ', 'g3.b.i5': '(5) ଅନ୍ୟ ସମସ୍ତ ITC',
  'g3.b.r1': '(1) ନିୟମ 38, 42, 43 ଓ ଧାରା 17(5)', 'g3.b.r2': '(2) ଅନ୍ୟାନ୍ୟ', 'g3.b.x1': 'କମ୍ପୋଜିସନ୍, ଛାଡ଼ ଓ ନିଲ୍ ରେଟେଡ୍ ସପ୍ଲାୟର୍ଙ୍କଠାରୁ', 'g3.b.x2': 'ନନ୍-GST ସପ୍ଲାଇ',
  'g3.b.cf': 'ଆଗରୁ ଆସିଥିବା ITC ବାଲାନ୍ସ (ଇଲେକ୍ଟ୍ରୋନିକ୍ କ୍ରେଡିଟ୍ ଲେଜର୍)', 'g3.b.int': 'ସୁଧ', 'g3.b.fee': 'ଲେଟ୍ ଫି',
