  'g3.for': 'GSTR-3B ହିସାବ: {p}', 'g3.k.out': 'ଆଉଟପୁଟ୍ ଟ୍ୟାକ୍ସ', 'g3.k.itc': 'ଆପଣ ବ୍ୟବହାର କରିପାରିବେ ସେହି ITC', 'g3.k.rcm': 'ରିଭର୍ସ ଚାର୍ଜ (କେବଳ କ୍ୟାସ୍)', 'g3.k.cash': 'କ୍ୟାସ୍‌ରେ ଦେବେ', 'g3.k.due': 'ଶେଷ ତାରିଖ',
  'g3.check': 'ଫାଇଲ୍ କରିବା ପୂର୍ବରୁ ଏଗୁଡ଼ିକ ଦେଖନ୍ତୁ', 'g3.h.pay': 'ଟ୍ୟାକ୍ସ ପେମେଣ୍ଟ (ଟେବୁଲ୍ 6.1)', 'g3.h.cf': 'ଇନପୁଟ୍ ଟ୍ୟାକ୍ସ କ୍ରେଡିଟ୍', 'g3.h.32': '3.2 ଅନ୍‌ରେଜିଷ୍ଟର୍ଡ୍ ବ୍ୟକ୍ତିଙ୍କୁ ଅନ୍ତଃରାଜ୍ୟ ସପ୍ଲାଇ',
  'g3.p.liab': 'ଦେବାକୁ ଥିବା ଟ୍ୟାକ୍ସ (ଫରୱାର୍ଡ ଚାର୍ଜ)', 'g3.p.byigst': 'IGST କ୍ରେଡିଟ୍‌ରୁ ଦିଆଗଲା', 'g3.p.bycgst': 'CGST କ୍ରେଡିଟ୍‌ରୁ ଦିଆଗଲା', 'g3.p.bysgst': 'SGST/UTGST କ୍ରେଡିଟ୍‌ରୁ ଦିଆଗଲା', 'g3.p.bycess': 'ସେସ୍ କ୍ରେଡିଟ୍‌ରୁ ଦିଆଗଲା',
  'g3.p.left': 'କ୍ରେଡିଟ୍ ପରେ ବି ଦେବାକୁ ବାକି', 'g3.p.rcm': 'ରିଭର୍ସ ଚାର୍ଜ ଟ୍ୟାକ୍ସ', 'g3.p.int': 'ସୁଧ ଓ ଲେଟ୍ ଫି', 'g3.p.cash': 'କ୍ୟାସ୍‌ରେ ମୋଟ ଦେବାକୁ', 'g3.p.avail': 'ଉପଲବ୍ଧ କ୍ରେଡିଟ୍', 'g3.p.cf': 'ପରବର୍ତ୍ତୀ ସମୟ ପାଇଁ ବଳକା କ୍ରେଡିଟ୍',
  'g3.note': 'ସେଟ୍-ଅଫ୍ CGST ଆଇନର ଧାରା 49 ଓ ନିୟମ 88A ଅନୁସାରେ: ପ୍ରଥମେ IGST କ୍ରେଡିଟ୍ ବ୍ୟବହାର ହୁଏ, ତା’ପରେ CGST ଓ SGST/UTGST କ୍ରେଡିଟ୍; CGST ଓ SGST କ୍ରେଡିଟ୍ କେବେ ବି ପରସ୍ପର ବିରୁଦ୍ଧରେ ବ୍ୟବହାର ହୁଏ ନାହିଁ; ରିଭର୍ସ ଚାର୍ଜ ଟ୍ୟାକ୍ସ କ୍ୟାସ୍‌ରେ ଦିଆଯାଏ। ଆପଣ ଫାଇଲ୍ କଲେ ପୋର୍ଟାଲ୍ ଶେଷ ସେଟ୍-ଅଫ୍ କରେ।',
  'g3.w.zr': 'ବିଲ୍ {no} ଏକ୍ସପୋର୍ଟ ବା SEZ ବିଲ୍, କିନ୍ତୁ ଏଥିରେ CGST/SGST ଦେଖାଯାଉଛି। ଜିରୋ ରେଟେଡ୍ ସପ୍ଲାଇରେ କେବଳ IGST ଲାଗେ।', 'g3.w.rcmv': 'ଭାଉଚର୍ {no}: ରିଭର୍ସ ଚାର୍ଜ ଟ୍ୟାକ୍ସ CGST + SGST ଭାବେ ନିଆଯାଇଛି। ସପ୍ଲାୟର୍ ଅନ୍ୟ ରାଜ୍ୟରେ ଥିଲେ (IGST) ବକ୍ସଗୁଡ଼ିକ ବଦଳାନ୍ତୁ।',
  'g3.w.nogstin': '{p} ଠାରୁ ପର୍ଚେଜ୍ ବିଲ୍ {no} ରେ ସପ୍ଲାୟର୍‌ର ଠିକ୍ GSTIN ନାହିଁ, ତେଣୁ ଏହାର ITC GSTR-2B ରେ ଦେଖାଯିବ ନାହିଁ।', 'g3.w.2b': 'ବକ୍ସ 4(A)(5) ର ITC ଆପଣଙ୍କ ସେଭ୍ ହୋଇଥିବା ପର୍ଚେଜ୍ ବିଲ୍ ଓ ଖର୍ଚ୍ଚରୁ ଆସେ। କେବଳ ସେତିକି ହିଁ କ୍ଲେମ୍ କରନ୍ତୁ ଯେତିକି ଆପଣଙ୍କ GSTR-2B ଦେଖାଉଛି; ତାହା କମ୍ ହେଲେ GSTR-2B ର ଅଙ୍କ ଟାଇପ୍ କରନ୍ତୁ।',
  'g3.w.neg': 'ଉପଲବ୍ଧ କ୍ରେଡିଟ୍ ଶୂନ୍ୟରୁ କମ୍: ଫେରାଇ ଦିଆଯାଇଥିବା କ୍ରେଡିଟ୍ ମୂଳ କ୍ରେଡିଟ୍‌ରୁ ଅଧିକ। ଅନ୍ତରଟି କ୍ୟାସ୍‌ରେ ଦେବାକୁ ପଡ଼ିବ; ଆପଣଙ୍କ ଏକାଉଣ୍ଟାଣ୍ଟଙ୍କୁ ପଚାରନ୍ତୁ।',
