  'nav.gstr2b': 'GSTR-2B ମ୍ୟାଚର୍', 'f.gstr2b': 'GSTR-2B ଓ ପର୍ଚେଜ୍ ବିଲ୍ ମ୍ୟାଚର୍',
  'g2.file': 'ଆପଣଙ୍କ GSTR-2B ଫାଇଲ୍ ଖୋଲନ୍ତୁ (JSON ବା Excel)', 'g2.drop': 'ବା ଫାଇଲ୍‌କୁ ଏଠାରେ ଛାଡ଼ନ୍ତୁ', 'g2.privacy': 'ଫାଇଲ୍ କେବଳ ଏହି ବ୍ରାଉଜରରେ ପଢାଯାଏ। ଏହା କେଉଁଠି ଅପଲୋଡ୍ ହୁଏ ନାହିଁ।',
  'g2.from': 'ଏହି ତାରିଖରୁ ପର୍ଚେଜ୍ ବିଲ୍', 'g2.to': 'ପର୍ଯ୍ୟନ୍ତ', 'g2.tol': 'ଅନୁମତି ଦିଆଯାଉଥିବା ଅନ୍ତର', 'g2.reg': 'GST ମ୍ୟାଚିଂ ଟୁଲ୍ ପାଇଁ ପର୍ଚେଜ୍ ରେଜିଷ୍ଟର୍', 'g2.regh': 'ଏହି ତାରିଖଗୁଡ଼ିକର ଆପଣଙ୍କ ପର୍ଚେଜ୍ ବିଲ୍‌ରୁ ବନିଥିବା, ପୋର୍ଟାଲର Matching Offline Tool ଲେଆଉଟ୍‌ରେ ଏକ Excel।',
  'g2.loaded': 'ଏହି ବ୍ରାଉଜରର ଡାଟା ହୋମ୍‌ରେ {n}ଟି ପର୍ଚେଜ୍ ବିଲ୍ ମିଳିଲା।', 'g2.reading': '{f} ପଢାଯାଉଛି…', 'g2.read': 'GSTR-2B ପଢାଗଲା: {n}ଟି ଡକ୍ୟୁମେଣ୍ଟ, GSTIN {g}, ପିରିୟଡ୍ {p}।',
  'g2.empty': 'ଏହି ଫାଇଲ୍‌ରେ କୌଣସି ବିଲ୍ ମିଳିଲା ନାହିଁ। GST ପୋର୍ଟାଲରୁ ଡାଉନଲୋଡ୍ କରିଥିବା GSTR-2B JSON ବା Excel ଖୋଲନ୍ତୁ।', 'g2.bad': 'ଏହି ଫାଇଲ୍ ପଢାଗଲା ନାହିଁ। GST ପୋର୍ଟାଲରୁ GSTR-2B ପୁଣି ଡାଉନଲୋଡ୍ କରନ୍ତୁ (JSON ବା Excel) ଓ ସେହି ଫାଇଲ୍ ଖୋଲନ୍ତୁ।',
  'g2.for': 'GSTIN {g} ପାଇଁ GSTR-2B ମ୍ୟାଚ୍, ପିରିୟଡ୍ {p}', 'g2.k.2b': 'GSTR-2B ରେ ଥିବା ITC', 'g2.k.books': 'ଆପଣଙ୍କ ପର୍ଚେଜ୍ ବିଲ୍‌ରେ ଥିବା ITC', 'g2.k.ok': 'ମେଳ ଖାଇଥିବା ITC', 'g2.k.n': 'ମେଳ ଖାଇଥିବା ଡକ୍ୟୁମେଣ୍ଟ',
  'g2.w.gstin': 'ଏହି GSTR-2B GSTIN {a} ପାଇଁ, କିନ୍ତୁ ବାଛିଥିବା ବିଜନେସ୍‌ର GSTIN {b}। ଠିକ୍ ବିଜନେସ୍ ବାଛନ୍ତୁ।',
  'g2.s.ok': 'ମେଳ ଖାଇଲା', 'g2.s.diff': 'ଅଙ୍କ ବା ତାରିଖ ଅଲଗା', 'g2.s.numdiff': 'ବିଲ୍ ନମ୍ବର ଅଲଗା', 'g2.s.only2b': 'GSTR-2B ରେ ଅଛି, ଆପଣଙ୍କ ପର୍ଚେଜ୍ ବିଲ୍‌ରେ ନାହିଁ', 'g2.s.onlybooks': 'ଆପଣଙ୍କ ପର୍ଚେଜ୍ ବିଲ୍‌ରେ ଅଛି, GSTR-2B ରେ ନାହିଁ',
  'g2.s.noitc': 'GSTR-2B କହୁଛି ITC ମିଳିବ ନାହିଁ', 'g2.s.nofile': 'ଏହି GSTR-2B ରେ କିଛି ନଥିବା ସପ୍ଲାୟର୍',
  'g2.h.ok': 'ସପ୍ଲାୟର୍, ନମ୍ବର, ଅଙ୍କ ଓ ତାରିଖ ସମାନ। ଏହି କ୍ରେଡିଟ୍ କ୍ଲେମ୍ କରିହେବ।', 'g2.h.diff': 'ଦୁଇଟିଯାକରେ ମିଳିଲା, କିନ୍ତୁ ଅଙ୍କ ଅଲଗା। ସପ୍ଲାୟର୍‌ଙ୍କ ସହିତ ବିଲ୍ ଦେଖନ୍ତୁ; GSTR-2B ଯେତିକି ଦେଖାଉଛି ସେତିକି ହିଁ କ୍ଲେମ୍ କରନ୍ତୁ।',
  'g2.h.numdiff': 'ସପ୍ଲାୟର୍ ଓ ଅଙ୍କ ସମାନ, କିନ୍ତୁ ବିଲ୍ ନମ୍ବର ଅଲଗା ଢଙ୍ଗରେ ଲେଖା। ସାଧାରଣତଃ ଟାଇପିଂ ଭେଦ: ଆପଣଙ୍କ ଏଣ୍ଟ୍ରି ଠିକ୍ କରନ୍ତୁ।',
  'g2.h.only2b': 'ସପ୍ଲାୟର୍ ଏହି ବିଲ୍ ରିପୋର୍ଟ କରିଛନ୍ତି, କିନ୍ତୁ ଆପଣଙ୍କ ଖାତାରେ ସେଭ୍ ହୋଇନାହିଁ। ଗୁଡ୍ସ ବା ସର୍ଭିସ୍ ପାଇଥିଲେ ଏଣ୍ଟ୍ରି କରନ୍ତୁ, ନଚେତ୍ ସପ୍ଲାୟର୍‌ଙ୍କୁ ଠିକ୍ କରିବାକୁ କୁହନ୍ତୁ।',
  'g2.h.onlybooks': 'ଏହି ତାରିଖଗୁଡ଼ିକର ଆପଣଙ୍କ ବିଲ୍ ଯାହା ସପ୍ଲାୟର୍ ଏପର୍ଯ୍ୟନ୍ତ ରିପୋର୍ଟ କରିନାହାଁନ୍ତି। GSTR-2B ରେ ଦେଖାନଯିବା ପର୍ଯ୍ୟନ୍ତ ITC କ୍ଲେମ୍ କରନ୍ତୁ ନାହିଁ; ସପ୍ଲାୟର୍‌ଙ୍କୁ ମନେ ପକାନ୍ତୁ।',
  'g2.h.noitc': 'ଯେଉଁ ବିଲ୍‌ରେ ପୋର୍ଟାଲ୍ ITC ମିଳିବ ନାହିଁ ବୋଲି ଦେଖାଉଛି (ଯେପରି ସପ୍ଲାୟର୍‌ଙ୍କ ରାଜ୍ୟରେ ପ୍ଲେସ୍ ଅଫ୍ ସପ୍ଲାଇ, ବା ସମୟ ସୀମା)।',
  'g2.h.nofile': 'ଏହି ସପ୍ଲାୟର୍‌ମାନେ ଏହି ପିରିୟଡ୍‌ରେ ଆପଣଙ୍କ କୌଣସି ବିଲ୍ ରିପୋର୍ଟ କରିନାହାଁନ୍ତି। ସେମାନେ GSTR-1 ଫାଇଲ୍ କରିନଥାଇପାରନ୍ତି।',
  'g2.c.sup': 'ସପ୍ଲାୟର୍', 'g2.c.no': 'ବିଲ୍ ନଂ', 'g2.c.date': 'ତାରିଖ', 'g2.c.txv': 'ଟ୍ୟାକ୍ସେବଲ୍ ଭ୍ୟାଲୁ', 'g2.c.tax': 'ଟ୍ୟାକ୍ସ', 'g2.c.txvb': 'ଟ୍ୟାକ୍ସେବଲ୍ (ଆପଣଙ୍କ ବିଲ୍)', 'g2.c.txv2': 'ଟ୍ୟାକ୍ସେବଲ୍ (2B)',
  'g2.c.taxb': 'ଟ୍ୟାକ୍ସ (ଆପଣଙ୍କ ବିଲ୍)', 'g2.c.tax2': 'ଟ୍ୟାକ୍ସ (2B)', 'g2.c.why': 'କ’ଣ ଅଲଗା', 'g2.c.itc': 'ଉପଲବ୍ଧ ITC', 'g2.c.rsn': 'କାରଣ', 'g2.c.bills': 'ବିଲ୍',
