  'td.no.c': 'TDS ନାହିଁ: ଏହି ବିଲ୍ ₹30,000 ବା ତା’ଠାରୁ କମ୍ ଏବଂ ବର୍ଷର ମୋଟ ₹1,00,000 ଭିତରେ ଅଛି।', 'td.no.m': 'TDS ନାହିଁ: ମାସର ପେମେଣ୍ଟ {l} ରୁ ଅଧିକ ନୁହେଁ।',
  'td.no.y': 'ଏପର୍ଯ୍ୟନ୍ତ TDS ନାହିଁ: ବର୍ଷର ମୋଟ {l} ଭିତରେ ଅଛି। ଯେଉଁ ପେମେଣ୍ଟରେ ତାହା ପାର ହେବ ସେଥିରେ କାଟନ୍ତୁ।', 'td.no.q': 'ଏପର୍ଯ୍ୟନ୍ତ TDS ନାହିଁ: ଏହି ବର୍ଷ ଏହି ବିକ୍ରେତାଙ୍କ ଠାରୁ କିଣା {l} ରୁ ଅଧିକ ନୁହେଁ।',
